# Positions within CAPTURED_WRITE_CHUNKS[0] (chunk 0's raw message array,
# header included) of the nibble pairs that encode, respectively, the
# patch-index byte (body offset 0x04) and the checksum bytes (body offset
# 0x0E-0x0F) — worked out by hand against the known decode, not guessed:
# reassembling the unmodified capture and checking which nibbles land on
# which decoded byte. See design/GP150_SUPPORT.md §3.1.
PATCH_INDEX_NIBBLE_POS = (32, 33)  # hi, lo
CHECKSUM_NIBBLE_POS = (52, 53, 54, 55)  # byte0 hi,lo then byte1 hi,lo
CAPTURED_SLOT = 199  # what CAPTURED_WRITE_CHUNKS already targets, unmodified


def build_chunks(slot: int, bad_checksum=None):
    """Copy CAPTURED_WRITE_CHUNKS, optionally repointing the target slot
    and/or corrupting the checksum — chunk 0 only, everywhere else
    untouched. `bad_checksum`, if given, is (hi_byte, lo_byte)."""
    chunks = [list(c) for c in CAPTURED_WRITE_CHUNKS]
    if slot != CAPTURED_SLOT:
        hi, lo = (slot >> 4) & 0xF, slot & 0xF
        p0, p1 = PATCH_INDEX_NIBBLE_POS
        chunks[0][p0], chunks[0][p1] = hi, lo
    if bad_checksum is not None:
        byte0, byte1 = bad_checksum
        c0, c1, c2, c3 = CHECKSUM_NIBBLE_POS
        chunks[0][c0], chunks[0][c1] = (byte0 >> 4) & 0xF, byte0 & 0xF
        chunks[0][c2], chunks[0][c3] = (byte1 >> 4) & 0xF, byte1 & 0xF
    return chunks

